WITH t AS (
  SELECT c.currency, y.customerid, SUM(y.consumption) AS total
  FROM customers c JOIN yearmonth y ON y.customerid = c.customerid
  WHERE y.date LIKE '2012%' AND c.currency IN ('CZK','EUR')
  GROUP BY c.currency, y.customerid
), a AS (
  SELECT currency, AVG(total) AS avg_total FROM t GROUP BY currency
)
SELECT ROUND((SELECT avg_total FROM a WHERE currency='CZK') - (SELECT avg_total FROM a WHERE currency='EUR'))::bigint AS diff;

