WITH ranked AS (
  SELECT preferred_foot, attacking_work_rate,
         ROW_NUMBER() OVER (PARTITION BY player_api_id ORDER BY date DESC, id DESC) AS rn
  FROM player_attributes
), cur AS (
  SELECT * FROM ranked WHERE rn = 1 AND preferred_foot = 'left'
    AND attacking_work_rate IN ('low','medium','high')
)
SELECT ROUND(100.0 * SUM(CASE WHEN attacking_work_rate = 'low' THEN 1 ELSE 0 END) / COUNT(*), 1) AS pct_low
FROM cur;

