WITH plus_atoms AS (
  SELECT a.atom_id, a.element, a.molecule_id FROM atom a JOIN molecule m ON m.molecule_id = a.molecule_id WHERE m.label = '+'
),
bonded AS (
  SELECT atom_id FROM connected UNION SELECT atom_id2 FROM connected
),
cnt AS (
  SELECT p.element, count(*) AS bonded_cnt FROM plus_atoms p JOIN bonded b ON b.atom_id = p.atom_id GROUP BY p.element
),
tot AS (SELECT count(*) AS total FROM plus_atoms)
SELECT c.element, round(100.0 * (SELECT count(*) FROM plus_atoms x WHERE x.element = c.element) / t.total, 2) AS pct
FROM cnt c CROSS JOIN tot t ORDER BY c.bonded_cnt DESC LIMIT 1;

